import{_ as r}from"./chunks/ec2ac0f5e01065296ba1.CPgyq7Tl.js";import{_ as o,C as p,o as n,c as i,j as t,a as l,E as s,a5 as m}from"./chunks/framework.DNkHA0lr.js";const M=JSON.parse('{"title":"简单的三点式线上商业模式","description":"","frontmatter":{"title":"简单的三点式线上商业模式","originalTitle":"The Simple 3 Point Online Business Model","date":"2022-03-01","originalUrl":"https://thedankoe.com/letters/the-simple-3-point-online-business-model/","minutes":7,"sourceHash":"bf6d7af9a5ec2701a6a20b9614851b2f15727dfb76f4de301b18516ae7bad3de","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-simple-3-point-online-business-model/"}]]},"headers":[],"relativePath":"letters/the-simple-3-point-online-business-model.md","filePath":"letters/the-simple-3-point-online-business-model.md"}'),h={name:"letters/the-simple-3-point-online-business-model.md"};function d(u,e,c,f,_,b){const a=p("ArticleMeta");return n(),i("div",null,[e[0]||(e[0]=t("h1",{id:"简单的三点式线上商业模式",tabindex:"-1"},[l("简单的三点式线上商业模式 "),t("a",{class:"header-anchor",href:"#简单的三点式线上商业模式","aria-label":'Permalink to "简单的三点式线上商业模式"'},"​")],-1)),s(a),e[1]||(e[1]=m('<p>在这个过度复杂化的世界里，我的使命是化繁为简。商业是世界上最简单的事情之一，但我们大多数人在童年时期从未接触过任何商业书籍。我们以为创业是留给那些拥有启动资金、前1%的顶尖技能，和/或庞大粉丝群加付费广告的人的。</p><p>让我们退后一步，看看要想达到每月赚取5000美元、1万美元甚至5万美元的目标，你到底需要什么。</p><p>这套三点式线上商业模式如下：</p><ol><li>社交媒体账号</li><li>电子邮件列表</li><li>报价 (Offer)</li></ol><p>它们相互关联，所以请坚持读到这封信的结尾，来了解它的全貌。</p><h2 id="第一点-社交媒体账号" tabindex="-1"><strong>第一点：社交媒体账号</strong> <a class="header-anchor" href="#第一点-社交媒体账号" aria-label="Permalink to &quot;**第一点：社交媒体账号**&quot;">​</a></h2><p>你的社交媒体账号就是你的新简历。</p><p>你的内容展示了你的专业知识、兴趣和个性。</p><p>随着付费广告变得越来越行不通，你的社交账号就是一个免费的自然流量源，你可以将流量导向你的报价（也就是你正在卖的东西）。</p><p>大多数人觉得社交媒体增长令人望而生畏。确实如此。但这里有经过验证的增长和变现方法。如果你完全不知道自己在做什么就开始尝试涨粉，那真是太蠢了……这就是为什么它一开始会让人觉得如此可怕。</p><p><em>附注：你不需要很多粉丝就能赚到6位数以上的收入。是的，粉丝很有帮助，帮助非常大，但你不是非有不可。你可以在建立杠杆的同时获得可观的收入。</em></p><p>所有这一切就像学习玩一场游戏（因为事实正是如此）。一开始，游戏很无聊，因为你不知道怎么玩。但你还是会去玩，去学习规则、基本原理、如何获胜，最终它会变得有趣。你想玩得更多，因为它开始变成一门艺术，而不仅仅是一门科学。</p><p>社交媒体也是如此。规则就是平台的服务条款。基本原理就是增长机制（你如何获得最大曝光并将那些读者转化为粉丝）。而机制会反映在你的内容中。以Twitter为例，机制就在于你是否有能力写出与你兴趣相关的、直击痛点的内容。</p><p>既然你的社交媒体账号是你品牌的门面，那你该如何开始呢？</p><h3 id="创建一个内容金字塔" tabindex="-1"><strong>创建一个内容金字塔</strong> <a class="header-anchor" href="#创建一个内容金字塔" aria-label="Permalink to &quot;**创建一个内容金字塔**&quot;">​</a></h3><p>你的内容金字塔包含你想谈论的所有主题，通常由2到3个核心支柱向下分支。我的是自我提升、线上商业以及对表现（performance）的灵性探讨。</p><p>你的可以是任何东西。如果有人在网上谈论某个话题并积累了受众，那你没有理由做不到。另一个很好的衡量标准是：如果你能和一个朋友就某个特定话题聊上几个小时，那为什么不在网上和大家聊聊呢？</p><p><img src="'+r+'" alt="The Content Pyramid"></p><p>内容金字塔</p><h3 id="打造一个值得关注的个人主页" tabindex="-1"><strong>打造一个值得关注的个人主页</strong> <a class="header-anchor" href="#打造一个值得关注的个人主页" aria-label="Permalink to &quot;**打造一个值得关注的个人主页**&quot;">​</a></h3><p>别在这一步想太多。其他人已经想得够多了。准备一张好看的头像，一段能回答“这对我（读者）有什么好处？”的引人注目的简介，并放上一个指向你报价的链接，向读者表明你是一个创作者——而不是一个消费者。</p><p>你要不断问自己一个问题：我的账号看起来像是一个应该有10万粉丝的账号吗？不像？那就改改吧。</p><h3 id="了解当前的主流增长策略-meta" tabindex="-1"><strong>了解当前的主流增长策略（Meta）</strong> <a class="header-anchor" href="#了解当前的主流增长策略-meta" aria-label="Permalink to &quot;**了解当前的主流增长策略（Meta）**&quot;">​</a></h3><p>再说一次，这是一场游戏。你需要了解什么样的内容能给新手带来最大的增长，因为那是增长最困难的时候。</p><p>试想一下，那些受欢迎的YouTuber并不是靠发旅行vlog才达到他们现在的地位的。他们把这场游戏玩得足够久，才到了现在随心所欲的境界。一开始，他们发布的是“怎么做（how-to）”类型的视频，以迎合算法。目前很流行的一种形式是“我尝试了X三十天”。</p><p>在Twitter上，当前的主流玩法是直击痛点的推文和Medium博客风格的长推。去加入那些讨论哪种内容效果最好的在线社区、群组和其他地方，或者干脆直接关注那些账号是怎么做增长的。</p><h3 id="保持持续性" tabindex="-1"><strong>保持持续性</strong> <a class="header-anchor" href="#保持持续性" aria-label="Permalink to &quot;**保持持续性**&quot;">​</a></h3><p>说到底，你不需要关注以上任何一点。你是<em>应该</em>关注，但如果你只是坚持下去并纠正错误长达一年，你也会拥有5位数的粉丝。</p><p>你的社交媒体账号将成为你推销报价、建立百万美元人脉以及为品牌未来建立杠杆的途径。如果你创办了一项服务业务，建立起现金流，并且拥有一大批受众——你现在就可以开启<em>任何</em>与你兴趣相关的业务，并让它取得成功。我计划很快创办一个咖啡品牌，仅仅是因为我他妈的太爱喝咖啡了。</p><p><a href="https://join.modernmastery.co/?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">如果你想要我的经典Twitter增长课程、一份按部就班的社交媒体增长路线图，以及超过154种其他的线上商业策略，请点击这里查看我的私密社区（MMHQ）。</a></p><h3 id="电子邮件列表" tabindex="-1"><strong>电子邮件列表</strong> <a class="header-anchor" href="#电子邮件列表" aria-label="Permalink to &quot;**电子邮件列表**&quot;">​</a></h3><p>一个不幸的事实是，你并不拥有你的社交媒体账号。它可能也不是一个适合<em>无时无刻</em>进行销售的地方。话虽如此，你应该从一开始就建立你的电子邮件列表。你并不<em>非得</em>给人发邮件或有固定的发送时间表，但不开始收集电子邮件是极其愚蠢的。万一你被封号了，它就会派上用场。你完全拥有你的列表。</p><p>一旦你有了时间，就开始写周报吧。当你准备好往其他方向发展时，这些周报未来可以转化为邮件序列、推特长推、博客文章或YouTube视频。目前，请专注于发展你的想法，并测试哪些内容能引起受众的共鸣。</p><p>当你准备好报价（产品或服务准备就绪）时，你可以创建自动邮件序列来进行自动化销售。然后，你所要做的就是在社交账号上发布内容，植入你的周报，你不需要做任何额外工作就能实现销售。</p><p>从欢迎序列开始。写一封欢迎邮件，告诉所有人你谈论的主题、你的品牌愿景，以及他们可以期待在未来的邮件中看到什么。然后，准备2-3封邮件来讲述你的故事，或者你致力于解决的核心痛点。之后，你可以将订阅者放入针对你报价的销售序列中。这些邮件应该提升他们对你所解决问题的认知水平，向他们展示解决方案，并加入一点紧迫感以促使他们购买。</p><p>仅凭一个社交媒体账号和电子邮件列表，随着时间的推移，你就能获得丰厚的收入。这是一个极度精益的一人企业模式。每天工作3-4小时（可能更少）——<em>前提是</em>你有一个扎实的报价 / 报价矩阵（offer stack）。</p><p><a href="https://join.modernmastery.co/?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">如果你想获取这份按部就班的电子邮件营销路线图，你可以在MMHQ中找到它。</a></p><h3 id="你的报价-offer" tabindex="-1"><strong>你的报价 (Offer)</strong> <a class="header-anchor" href="#你的报价-offer" aria-label="Permalink to &quot;**你的报价 (Offer)**&quot;">​</a></h3><p>对于初学者来说，你的报价就是你的产品或服务。也就是你<em>卖</em>的东西。如果你想赚钱，你就必须卖点什么，这是理所当然的（但没多少人懂这个道理）。在你连主动收入都没有的时候，别再试图去赚被动收入了。</p><p>“Dan，那我该卖什么呢？”</p><p>你对什么感兴趣？你在什么方面有经验？你在什么领域取得过成果？你有没有通过试错解决过生活中的某个问题？你能否帮助人们避开这些试错？<em>你关注的人都在卖些什么？你能卖同样的东西吗？（买过的人还会再买，不要重新发明轮子）。</em></p><p>我尝试做了3年的自由职业，最终取得了成功，然后我写了一本书，介绍我是如何做到的。我知道讲自由职业的书已经卖得很好了，所以我创作了自己的书，把它卖给了那些比信任竞争对手更信任我的人（你的个人品牌能够消除竞争）。</p><p>我喜欢计划本，并从中获得了成果，于是我创建了自己的计划本，拿去售卖（你们中有些人知道它叫力量计划本，Power Planner）。</p><p>在做完自由职业后，我创建了一项营销咨询服务（Offer），目标群体是创作者。为什么？因为我看到其他人在卖这个，我知道如何带领创作者从A点走到B点，于是我以8000美元的价格售出。这对某些人来说听起来很荒谬，因为你还没开始。再说一遍，就像玩游戏一样，你根本不知道游戏后期会发生什么，因为你还没有迈出第一步。</p><p>现在，这里有几件事需要考虑：</p><ul><li>人们不在乎你产品或服务里的所有细节，他们在乎的是你能给他们带来的<em>具体</em>结果（以及所有能帮他们获得那个结果的东西）</li><li><a href="https://youtu.be/kC1IvnzM_-A?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">即使你还没有成绩，你也可以创造一个令人无法拒绝的承诺（guarantee）。</a> 这才是最能让你赚钱的东西。</li><li>你必须让从A点（遇到问题）到B点（问题解决）的过程尽可能简单直接。你让买家越容易把它落实到自己的生活中，就越好。系统高于一切。</li><li>别再试图解决每一个问题。专注于一个迫在眉睫的、生物本能上的核心痛点。测试不同的角度，并加倍投入，直到你看到你想要的销量。</li></ul><p>说到底，我们要么面临流量问题，要么面临报价（Offer）问题。JK Molina说得最好：</p><blockquote><p>“要么是流量问题，要么是报价问题”这个理念改变了我的一生\\</p><p>没钱？优化你的报价或者搞更多流量\\</p><p>没女孩？提升自己（报价）或者去见更多女孩（流量）\\</p><p>永远都有解决办法。无非就是这两者之一。</p><p>— JK MOLINA (@OneJKMolina) <a href="https://twitter.com/OneJKMolina/status/1492150948831109120?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2022年2月11日</a></p></blockquote><p>如果你赚不到钱，这就是原因。除此之外的任何问题，都只是持续性和迭代的问题。</p><p><a href="https://join.modernmastery.co/?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">如果你想要我的教父级报价框架（Godfather Offer Framework）和高阶营销路线图……再说一次，它在MMHQ里，哈哈</a>（所有东西都在MMHQ里）。</p><p>就写到这里。祝我的朋友们周末愉快，让它充满意义。</p><p><em><strong>Dan Koe</strong></em></p><hr><p><a href="/en/letters/the-simple-3-point-online-business-model">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',54))])}const T=o(h,[["render",d]]);export{M as __pageData,T as default};
